mapper.select:
SELECT share_log_id, order_no, order_title, order_brief, distributor_id, account_type, distributor_name, sub_merchant_id, share_percentage, share_amount, share_status, canceled, creator, create_time, modifier, update_time, venue_id, deleted FROM marketing_order_profit_sharing WHERE deleted = 0 AND mct_no = #{mctNo, jdbcType=VARCHAR}
AND create_time > #{startDate, jdbcType=TIMESTAMP}
AND create_time < #{endDate, jdbcType=TIMESTAMP}
AND (order_brief LIKE CONCAT('%', #{keyword}, '%') OR distributor_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY share_log_id DESC
